ret = mix(ret, 0.0 ,clamp01(GetBlur1(uv).z*1.2));
ret = mix(ret,ret*vec3( 2.0 , 1.0 , 0.0),GetPixel(uv).z * 3.0);
ret = mix(ret*vec3( 1.0 , 1.0 , 1.0),vec3( 0.0 ,-0.2, -1.0),GetBlur1(uv2).x*2.4);
vec2 uv3 = uv + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 6.0 + vec2(-dy.z,dx.z)*(vec2(1.0)/uTexSize) * 24.0;
vec2 uv31 = uv + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 6.0 - vec2(-dy.z,dx.z)*(vec2(1.0)/uTexSize) * 24.0;
float x = max(GetPixel(uv3).x,GetPixel(uv31).x);
ret = mix(ret,vec3( 0.0 ,0.5, 1.0)*(0.9+(-dx+dy).x),x);
